'use strict';
(()=>{const $=id=>document.getElementById(id),el=(t,text,c)=>{const n=document.createElement(t);if(text!==undefined)n.textContent=text;if(c)n.className=c;return n;};let serverToday;
const today=()=>serverToday||new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function state(p){if(p.access_state)return p.access_state;if(p.is_active===false)return 'disabled';if(p.is_full_time)return 'active';if(p.placement_start&&p.placement_start>today())return 'scheduled';if(p.placement_end&&p.placement_end<today())return 'expired';return 'active';}
const date=value=>value?new Date(value+'T12:00:00Z').toLocaleDateString('en-CA',{month:'short',day:'numeric',year:'numeric',timeZone:'America/Toronto'}):'Not set';
function label(p){const s=state(p),status={active:'Active',scheduled:'Upcoming',expired:'Placement ended',disabled:'Access removed'}[s]||s;return status+' · '+(p.is_full_time?'Full-time':p.placement_end?'Ends '+date(p.placement_end):'Dates not set');}
function archived(p){return !p.is_full_time&&['expired','disabled'].includes(state(p));}
function badge(p){const n=el('span',label(p),'person-access-badge');n.dataset.state=state(p);return n;}
function form(root,person,api,onSaved=()=>{}){const box=el('section',undefined,'portal-manager portal-role-panel'),heading=el('h2','Employment and placement'),summary=badge(person);box.append(heading,summary,el('p','Co-op access remains active through 11:59 p.m. Toronto time on the end date. Extending dates restores date-based access and removes the person from the archive.'));const form=el('form',undefined,'portal-form'),fullLabel=el('label','Full-time employee'),full=el('input');full.type='checkbox';full.checked=!!person.is_full_time;fullLabel.prepend(full);fullLabel.className='portal-full-time';form.append(fullLabel);const dates=el('div',undefined,'placement-date-fields');const input=(label,value)=>{const lab=el('label',label,'portal-field'),n=el('input');n.type='date';n.value=value||'';lab.append(n);dates.append(lab);return n;},start=input('Placement start',person.placement_start),end=input('Placement end',person.placement_end);form.append(dates);const update=()=>{start.disabled=end.disabled=full.checked;start.required=end.required=!full.checked;end.min=start.value||'';};full.onchange=update;start.onchange=update;update();const save=el('button','Save placement','primary'),status=el('p',undefined,'portal-note');save.type='submit';status.setAttribute('role','status');form.append(save,status);box.append(form,el('p','Full-time employees do not expire by placement date. Manual removal of access still applies.','portal-note'));root.append(box);form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{const r=await api.db.rpc('set_placement',{target:person.id,full_time:full.checked,start_date:full.checked?null:start.value,end_date:full.checked?null:end.value});if(r.error)throw r.error;const result=await api.db.rpc('portal_people_directory');if(result.error)throw result.error;const fresh=result.data.find(p=>p.id===person.id);Object.assign(person,fresh);onSaved();summary.textContent=label(person);summary.dataset.state=state(person);status.textContent='Placement saved. '+(state(person)==='active'?'Access is active.':state(person)==='expired'?'This co-op is archived and cannot enter the workspace.':state(person)==='scheduled'?'Access will begin on the start date.':'Manual access removal remains in effect.');if(person.id===api.user().id){await api.reloadProfile();}}catch(err){status.textContent='Not saved: '+err.message;}finally{save.disabled=false;}};}
function warnings(people,work){const rows=[];for(const p of people){if(p.is_full_time)continue;if(!p.placement_end)rows.push(p.display_name+': placement end date is not set.');else if(work.work_kind==='project'&&work.due_date&&work.due_date>=p.placement_end)rows.push(p.display_name+': due date is on or after placement ends on '+date(p.placement_end)+'.');else if(work.work_kind==='task'&&(!work.recurrence_end||work.recurrence_end>=p.placement_end))rows.push(p.display_name+': recurrence stops at placement end on '+date(p.placement_end)+'.');if(work.work_kind==='project'&&p.placement_start&&work.due_date&&work.due_date<p.placement_start)rows.push(p.display_name+': due date is before the placement starts.');}return rows;}
window.GuhuzaPeople={state,label,badge,archived,date,form,warnings,setToday:d=>{serverToday=d;},today};})();
